def cmd_rename(old, new, dry_run):
    old_key, new_key = old.strip().lower(), new.strip().lower()
    locs = load_locations()
    if old_key not in locs:
        print(f"No saved location named '{old_key}'.")
        return
    if dry_run:
        print(f"[DRY RUN] Would rename: '{old_key}' to '{new_key}'")
        return
    locs[new_key] = locs.pop(old_key)
    save_locations(locs)
    print(f"Renamed saved location: '{old_key}' to '{new_key}'")


